    public int NumberOfAttendees { get; set; } = 1;
    public EMeetingMode MeetingMode { get; set; } = EMeetingMode.InPerson;
    public string? OnlineMeetingUrl { get; set; }

    public EBookingStatus Status { get; set; } = EBookingStatus.Approved;
    public Guid? ApprovedBy { get; set; }
    public DateTimeOffset? ApprovedDate { get; set; }
    public string? CancelledReason { get; set; }
    public string? RejectedReason { get; set; }

    public bool IsRecurring { get; set; } = false;
    public Guid? RecurrenceBookingId { get; set; }
    public string? RecurrenceRule { get; set; }
    public bool IsPrivate { get; set; } = false;

    public ICollection<MeetingAttendee> Attendees { get; set; } = new List<MeetingAttendee>();
    public ICollection<MeetingServiceRequest> ServiceRequests { get; set; } = new List<MeetingServiceRequest>();
}
