namespace MasterData.Data.Persistence.Configurations.MeetingRooms;

public class RoomFacilityMappingConfiguration : IEntityTypeConfiguration<RoomFacilityMapping>
{
    public void Configure(EntityTypeBuilder<RoomFacilityMapping> builder)
    {
        builder.ToTable("room_facility_mapping");
        builder.HasKey(x => x.Id);

        builder.HasIndex(x => new { x.MeetingRoomId, x.MeetingFacilityId, x.DeletedDate });

        builder.Property(x => x.Note).HasMaxLength(500);

        builder.HasOne(x => x.MeetingRoom)
            .WithMany(x => x.RoomFacilities)
            .HasForeignKey(x => x.MeetingRoomId)
            .OnDelete(DeleteBehavior.Cascade);

        builder.HasOne(x => x.MeetingFacility)
            .WithMany(x => x.RoomFacilities)
            .HasForeignKey(x => x.MeetingFacilityId)
            .OnDelete(DeleteBehavior.Restrict);

        builder.HasOne(x => x.Asset)
            .WithMany()
            .HasForeignKey(x => x.AssetId)
            .OnDelete(DeleteBehavior.SetNull);

        builder.HasQueryFilter(x => !x.DeletedDate.HasValue);
    }
}
