"using Contracts.Attributes;
using Contracts.Domains;
using Contracts.Domain.Interfaces;
using Shared.Enums;

namespace ServiceDesk.Data.Entities.MeetingRooms;

[AutoFilter]
[CodeGeneration("Đặt phòng họp", EContextScope.ServiceDesk, typeof(MeetingBooking))]
public record MeetingBooking : EntityAuditBase<Guid>, ITicketAccessControl, ISyncsChildren<MeetingBooking>
{
    public string CategoryCode => nameof(MeetingBooking);

    public IEnumerable<Guid> GetRelatedUserIds()
    {
        var ids = new HashSet<Guid> { OrganizerUserId };
        if (ApprovedByUserId.HasValue) ids.Add(ApprovedByUserId.Value);
        if (CancelledByUserId.HasValue) ids.Add(CancelledByUserId.Value);
        if (Attendees != null)
        {
            foreach (var a in Attendees)
            {
                if (a.UserId.HasValue && !a.DeletedDate.HasValue)
                    ids.Add(a.UserId.Value);
            }
        }
        return ids;
    }

    public string Code { get; set; } = default!;
    public string Title { get; set; } = default!;
    public string? Description { get; set; }

    // Thông tin phòng họp (Snapshot từ MasterData MeetingRoom)
    public Guid MeetingRoomId { get; set; }
    public string? MeetingRoomCodeSnapshot { get; set; }
    public string? MeetingRoomNameSnapshot { get; set; }
    public string? LocationDetailsSnapshot { get; set; }

    // Thời gian cuộc họp
    public DateTimeOffset StartTime { get; set; }
    public DateTimeOffset EndTime { get; set; }
    public DateTimeOffset? ActualStartTime { get; set; }
    public DateTimeOffset? ActualEndTime { get; set; }

    // Người đặt & Đơn vị tổ chức
    public Guid OrganizerUserId { get; set; }
    public string? OrganizerNameSnapshot { get; set; }
    public string? OrganizerEmailSnapshot { get; set; }
